import { Facebook, Linkedin, Youtube } from 'lucide-react';
import { Link } from '@tanstack/react-router';
import type { SiteSettings, PracticeArea } from '../types';
function Social({label}:{label:string}){const l=label.toLowerCase();if(l.includes('linkedin'))return <Linkedin/>;if(l.includes('facebook'))return <Facebook/>;if(l.includes('youtube'))return <Youtube/>;return <span aria-hidden>{label.slice(0,1)}</span>}
export function SiteFooter({settings,areas}:{settings:SiteSettings;areas:PracticeArea[]}){const socials=(settings.socials||[]).filter(s=>s.url&&s.url!=='#');return <footer className="site-footer"><div className="ui-container footer-grid"><div className="footer-brand"><div className="brand light"><span className="brand-seal" aria-hidden>Ⅱ</span><span><b>{settings.firmName}</b><small>{settings.tagline}</small></span></div><p>A dedicated law firm committed to practical, responsive and result-oriented legal service.</p>{socials.length>0&&<div className="socials">{socials.map(s=><a href={s.url} target="_blank" rel="noreferrer" aria-label={s.label} key={s.label}><Social label={s.label}/></a>)}</div>}</div><div><h3>Quick Links</h3><Link to="/about">About Us</Link><Link to="/practice-areas">Area of Practice</Link><Link to="/team">Our Team</Link><Link to="/insights">Insights</Link><Link to="/contact">Contact Us</Link></div><div><h3>Our Services</h3>{areas.slice(0,6).map(a=><Link key={a.id} to="/practice-areas/$slug" params={{slug:a.slug}}>{a.title}</Link>)}</div><div><h3>Contact Us</h3><a href={`tel:${settings.phone.replace(/[^+\d]/g,'')}`}>{settings.phone}</a><a href={`mailto:${settings.email}`}>{settings.email}</a><p>{settings.address}</p></div></div><div className="ui-container footer-bottom"><span>© {new Date().getFullYear()}, {settings.firmName}. All Rights Reserved.</span><span>Justice. People. Progress.</span></div></footer>}
