import { useMemo, useState } from 'react';
import { Rating } from '@kka/site-ui';
import type { Testimonial } from '../types';
export function TestimonialCarousel({items}:{items:Testimonial[]}){const [active,setActive]=useState(0);const ordered=useMemo(()=>items.map((x,i)=>({...x,offset:(i-active+items.length)%items.length})),[items,active]);return <div className="testimonial-shell"><div className="testimonial-track">{ordered.map(x=><article key={x.id} data-offset={x.offset}><Rating value={x.rating}/><h3>“{x.title}”</h3><p>“{x.quote}”</p><small>— {x.source}</small></article>)}</div><div className="carousel-controls"><button onClick={()=>setActive((active-1+items.length)%items.length)} aria-label="Previous testimonial">←</button><div className="carousel-dots">{items.map((_,i)=><button key={i} className={i===active?'active':''} onClick={()=>setActive(i)} aria-label={`Show testimonial ${i+1}`}/>)}</div><button onClick={()=>setActive((active+1)%items.length)} aria-label="Next testimonial">→</button></div></div>}
