import { useState } from 'react';
import { Container, Eyebrow, Heading, Section } from '@kka/site-ui';
import { searchSite } from '../lib/api';
export function SearchPage(){const [q,setQ]=useState('');const [results,setResults]=useState<{type:string;title:string;url:string;excerpt:string}[]>([]);const [loading,setLoading]=useState(false);const [error,setError]=useState('');const [searched,setSearched]=useState(false);async function submit(e:React.FormEvent){e.preventDefault();if(q.trim().length<2)return;setLoading(true);setError('');setSearched(true);try{setResults(await searchSite(q.trim()))}catch(e){setResults([]);setError(e instanceof Error?e.message:'Search is unavailable. Please try again.')}finally{setLoading(false)}}return <><section className="page-hero small"><Container><Eyebrow>Search</Eyebrow><Heading as="h1">FIND A PRACTICE, PROFESSIONAL OR INSIGHT.</Heading></Container></section><Section><Container><form className="search-form" onSubmit={submit}><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search the firm..." aria-label="Search"/><button>{loading?'Searching…':'Search'}</button></form><div className="search-results" aria-live="polite">{error&&<p role="alert">{error}</p>}{searched&&!loading&&!error&&!results.length&&<p>No matching public content was found.</p>}{results.map((r,i)=><a href={r.url} key={`${r.url}-${i}`}><small>{r.type}</small><h3>{r.title}</h3><p>{r.excerpt}</p></a>)}</div></Container></Section></>}
