import { Link } from '@tanstack/react-router';
import { Container, Eyebrow, Heading, ReadingContainer, Section } from '@kka/site-ui';
import type { Publication, SiteBootstrap } from '../types';
import { PageHero } from './AboutPage';
import { SafeImage } from '../components/SafeImage';
import { Seo } from '../components/Seo';
export function InsightsPage({data}:{data:SiteBootstrap}){return <><Seo settings={data.settings} title="Legal Insights" description="Articles, explainers, video and commentary from Kariuki Kagunda & Co. Advocates."/><PageHero eyebrow="Legal Insights" title="PRACTICAL LEGAL THINKING FOR A CHANGING KENYA." copy="Articles, explainers, video and commentary from the firm."/><Section><Container><div className="article-grid featured-grid">{data.publications.map((p,i)=><Link className={`article-card ${i===0?'feature':''}`} key={p.id} to="/insights/$slug" params={{slug:p.slug}}><SafeImage asset={p.cover} fallback={i===0?'/assets/media-feature.png':'/assets/media-ip.png'} alt={p.title}/><div><small>{p.kind} · {new Date(p.publishedAt).toLocaleDateString('en-KE',{day:'numeric',month:'short',year:'numeric'})}</small><h3>{p.title}</h3><p>{p.excerpt}</p><span>{p.kind==='VIDEO'?'Watch':'Read'} →</span></div></Link>)}</div></Container></Section></>}
export function InsightPage({publication,data}:{publication:Publication;data:SiteBootstrap}){const related=data.publications.filter(p=>p.id!==publication.id&&p.practiceAreas.some(a=>publication.practiceAreas.includes(a))).slice(0,3);const seo=(publication.seo||{}) as any;return <article className="article-page"><Seo settings={data.settings} title={seo.title||publication.title} description={seo.description||publication.excerpt} image={publication.cover?.url}/><header className="article-header"><ReadingContainer><Eyebrow>{publication.kind==='VIDEO'?'Video':'Legal Insight'}</Eyebrow><Heading as="h1">{publication.title}</Heading><p>{publication.excerpt}</p><div className="article-meta"><span>{new Date(publication.publishedAt).toLocaleDateString('en-KE',{day:'numeric',month:'long',year:'numeric'})}</span>{publication.duration&&<span>{publication.duration}</span>}{publication.author&&<Link to="/team/$slug" params={{slug:publication.author.slug}}>By {publication.author.name}</Link>}</div></ReadingContainer></header><div className="article-cover"><SafeImage asset={publication.cover} fallback="/assets/media-feature.png" alt={publication.title}/>{publication.kind==='VIDEO'&&<div className="video-play-overlay" aria-hidden>▶</div>}</div><Section><ReadingContainer className="prose article-body">{publication.body.split(/\n\n+/).filter(Boolean).map((p,i)=><p key={i}>{p}</p>)}<p className="legal-note">This publication is general information and is not a substitute for advice on a specific matter.</p></ReadingContainer></Section>{related.length>0&&<Section tone="ivory"><Container><Eyebrow>Related</Eyebrow><Heading>MORE FROM THE FIRM.</Heading><div className="article-grid">{related.map(p=><Link className="article-card" key={p.id} to="/insights/$slug" params={{slug:p.slug}}><SafeImage asset={p.cover} fallback="/assets/media-ip.png" alt={p.title}/><div><small>{p.kind}</small><h3>{p.title}</h3><p>{p.excerpt}</p><span>Read →</span></div></Link>)}</div></Container></Section>}</article>}
