import { Container, Eyebrow, Heading, Section } from '@kka/site-ui';
import type { SiteBootstrap } from '../types';
import { LeadForm } from '../components/LeadForm';
import { Seo } from '../components/Seo';
export function ContactPage({data}:{data:SiteBootstrap}){return <><Seo settings={data.settings} title="Contact Us" description="Contact Kariuki Kagunda & Co. Advocates for a legal enquiry or consultation."/><section className="contact-hero"><Container><Eyebrow>Contact Us</Eyebrow><Heading as="h1">LET’S START A CONVERSATION.</Heading><p>Tell us the essential facts. Our team can review the enquiry and route it to the appropriate practice area.</p></Container></section><Section><Container className="contact-layout"><div className="contact-form-wrap"><Eyebrow>Work With Us</Eyebrow><Heading>HOW CAN WE HELP?</Heading><LeadForm areas={data.practiceAreas}/></div><aside className="contact-info"><div className="contact-image"><img src="/assets/consultation-partner.png" alt="Legal professional at Kariuki Kagunda & Co. Advocates"/></div><div className="contact-gold"><Heading>YOUR LEGAL PARTNER FOR A BRIGHTER TOMORROW.</Heading></div><div className="contact-details"><h3>Contact information</h3><a href={`tel:${data.settings.phone.replace(/\s/g,'')}`}>{data.settings.phone}</a><a href={`mailto:${data.settings.email}`}>{data.settings.email}</a><p>{data.settings.address}</p></div></aside></Container></Section></>}
